function mesh3_set_texture(mesh, texture) end

--- scroll a custom mesh's texture coordinates
---@param mesh integer
---@param u number
---@param v number
function mesh3_set_uv_offset(mesh, u, v) end

--- draw this mesh in the blended pass: depth-tested but NOT depth-written, so it's occluded by solid geometry and occludes nothing. Instances within one transparent mesh aren't sorted against each other, so build overlapping translucent surfaces back-to-front, or keep them from overlapping.
---@param mesh lightuserdata|table
---@param enabled boolean
function mesh3_set_transparent(mesh, enabled) end

--- register sparse morph targets on a skinned mesh. The blob is little-endian: u32 target_count, then per target: u32 entry_count, then per target: entry_count * (u32 corner_index, f32 dx, f32 dy, f32 dz) Positions only. Normals are left alone: a facial deformation is small enough that the shading error is invisible, and carrying delta normals would double the data for something nobody would see.
---@param mesh lightuserdata|table
---@param blob any
function mesh3_set_morphs(mesh, blob) end

--- weights is an array of one number per target. Rebuilds the morphed rest pose. Call only when the weights CHANGE; skinning re-reads the result every frame regardless.
---@param mesh lightuserdata|table
---@param weights number[]
function mesh3_morph(mesh, weights) end

